/*
 * Four DC motors on two TB6612FNG drivers, PWM generated by MCPWM.
 *
 * Each wheel uses one MCPWM operator with two generators on IN1 / IN2
 * (PWMx pin tied high). Slow-decay drive/brake modulation:
 *   forward : IN1 = 1,           IN2 = low for duty, else high  (drive / short-brake)
 *   reverse : IN1 = low for duty, IN2 = 1
 *   zero    : IN1 = IN2 = 1 (brake)
 * Slow decay gives a near-linear duty-to-speed curve, which suits the PI loop.
 *
 * Operators: group 0 has three (FL, RL, FR), group 1 has the fourth (RR).
 */
#pragma once

#include <stdbool.h>

#include "esp_err.h"

esp_err_t motors_init(void);
/* duty in [-1, 1] per wheel, index order FL, RL, FR, RR (aegis_config.h) */
void motors_set(const float duty[4]);
/* STBY low: both drivers high-impedance regardless of PWM */
void motors_enable(bool on);
